#include <vector>
using namespace std;

class Solution {
    bool hasZero(int n) {
        while (n) {
            if (n % 10 == 0) return true;
            n /= 10;
        }
        return false;
    }
public:
    vector<int> getNoZeroIntegers(int n) {
        for (int i = 1; i < n; ++i) {
            if (!hasZero(i) && !hasZero(n - i))
                return {i, n - i};
        }
        return {};
    }
};
